/* ---------- Set limit ---------- */
.slx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px;container:slx/inline-size}
/* the budget figure shares the title's line: the two sit on one baseline */
.slx-h{display:flex;align-items:first baseline;justify-content:space-between}
.slx-h>div{display:flex;flex-direction:column;font-size:14px}
.slx-h b{font-weight:500}
.slx-h .muted{font-size:12px}
/* the cap is labelled and reads as a field at rest (owner, 28 Nov): "Cap" in the muted text, then a small field with its $ in
   front, white with the dimmed field edge, which steps up one grey while you type. A cap you can't change is the figure alone */
.slx-cap{display:inline-flex;align-items:baseline;gap:var(--dm-s-2)}
.slx-v{display:inline-flex;align-items:baseline;font-size:14px;font-weight:500!important;letter-spacing:-.02em;padding:3px var(--dm-s-2);border-radius:var(--dm-r-field);cursor:text;transition:box-shadow .2s var(--dm-ease)}
.slx-v:has(input){background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.slx-v:has(input):focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.slx-v .cur{color:var(--dm-muted);font-weight:400;margin-right:2px}
@supports (corner-shape:squircle){.slx-v{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.slx-in{width:3ch;min-width:1ch;padding:0;margin:0;border:0;background:none;font:inherit;font-variant-numeric:tabular-nums;letter-spacing:inherit;color:inherit;text-align:right;outline:none;caret-color:var(--dm-accent-fg,var(--dm-accent))}
/* the bar, with the same room above and below its knob. The cap it sets is the figure in the head, so the knob carries no
   amount of its own over it */
.slx-bar{position:relative;height:12px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-chip);margin:var(--dm-s-2) 0;touch-action:none;cursor:pointer}
.slx-used{position:absolute;left:0;top:0;bottom:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-accent-mark,var(--dm-accent));transition:width .8s var(--dm-ease);z-index:1}
/* the forecast: stripes of the accent, and the legend's swatch is the same stripes */
.slx{--dm-slx-hatch:repeating-linear-gradient(-45deg,color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent) 0 3px,color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 18%,transparent) 3px 6px)}
.slx-fc{position:absolute;left:0;top:0;bottom:0;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-slx-hatch);transition:width .8s var(--dm-ease)}
/* the knob: ink, with a quiet grey ring while it is pointed at or dragged (a highlight is never a coloured glow) */
.slx-k{position:absolute;top:50%;width:6px;height:26px;margin:-13px 0 0 -3px;border-radius:var(--dm-r-pill);background:var(--dm-fg);z-index:2;cursor:grab;transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
.slx-k.drag{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 12%,transparent)}
@media (hover:hover) and (pointer:fine){.slx-k:hover{box-shadow:0 0 0 4px color-mix(in srgb,var(--dm-fg) 12%,transparent)}}
.slx-k.drag{cursor:grabbing}
.slx-lg{display:flex;gap:var(--dm-s-4);font-size:12px}
.slx-lg span{display:flex;align-items:center;gap:6px}
.slx-lg b{color:var(--dm-fg);font-weight:500}
.slx-lg i{width:8px;height:8px;border-radius:var(--dm-r-tiny,3px)}
.slx-lg i.fc{background:var(--dm-slx-hatch)}
/* the line under the bar. On track: a neutral line with the green tick. Over: a warning notice (owner, 18 Nov), a faint
   warning tint as wide as the content, the filled warning sign in the warning mark, and the words in the text colour */
.slx-warn{font-size:12.5px;line-height:18px;min-height:18px}
.slx-warn .o{display:flex;align-items:center;gap:var(--dm-s-2);color:var(--dm-fg2)}
.slx-warn .o svg{flex:none;color:var(--dm-ok-mark)}
.slx-warn .w{display:grid;grid-template-columns:16px minmax(0,1fr);align-items:start;gap:var(--dm-s-2);padding:var(--dm-s-2) 10px;text-wrap:pretty;border-radius:var(--dm-r-in);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent);color:var(--dm-fg)}
.slx-wi{width:16px;height:16px;margin-top:1px;overflow:visible}
.slx-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.slx-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.slx-opt{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12.5px}
.slx-sg button{font-size:12px;height:28px;padding:0 10px}
/* narrow: the choice under its label, as wide as the bar, its three options sharing it */
@container slx (max-width:360px){
  .slx-opt{flex-direction:column;align-items:stretch;gap:var(--dm-s-2)}
  .slx-sg{display:flex}
  .slx-sg button{flex:1;padding:0 6px}
}
:root:not([data-style="soft"],[data-style="clean"]) .slx-warn .w:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* Clean (owner, 17 and 20 Nov): its content 16px from each edge; the bar has Clean's soft inner shadow, as Slider's rail does */
:root[data-style="clean"] .slx.panel,:root [data-style="clean"] .slx.panel,:root [data-style="clean"].slx.panel{padding:16px}
:root[data-style="clean"] .slx-bar,:root [data-style="clean"] .slx-bar,:root [data-style="clean"].slx-bar{box-shadow:var(--dm-track-ring)}

DM.def('set-limit', (r, c) => {
  const bar = $('.slx-bar', r), k = $('.slx-k', r), v = $('.slx-v', r), used = $('.slx-used', r), fc = $('.slx-fc', r), warn = $('.slx-warn', r);
  const MIN = 50, MAX = 500, SPENT = 128, FC = 184; let cap = 200, mode = 'pause';
  const pct = x => (x - MIN) / (MAX - MIN) * 100;
  const vin = $('.slx-in', r), fit = () => { vin.style.width = Math.max(1, vin.value.length) + 'ch'; };
  function upd(anim){
    k.style.left = pct(cap) + '%'; k.setAttribute('aria-valuenow', cap); k.setAttribute('aria-valuetext', '$' + cap);
    // while someone types, the field keeps what they typed
    if (document.activeElement !== vin){ vin.value = cap; fit(); }
    used.style.width = Math.min(100, SPENT / cap * pct(cap)) + '%'; fc.style.width = Math.min(pct(cap), FC / cap * pct(cap)) + '%';
    const over = FC > cap;
    const h = over ? `<span class="w"><svg class="slx-wi" viewBox="0 0 24 24" aria-hidden="true"><path class="a" d="M12 3.6 2.6 19.9h18.8z"/><path class="b" d="M12 9.6v4.4M12 17v.01"/></svg><span>Forecast passes your cap around Oct 27. Runs will ${mode === 'pause' ? 'pause' : mode === 'ask' ? 'wait for you' : 'keep going'}.</span></span>` : `<span class="o">${I('ok','xs')}<span>On track. About <span class="slx-left">$${cap - FC}</span> left at month end.</span></span>`;
    // a new message comes in with the entrance; while it stays the same, only the amount left follows the cap
    if (warn.dataset.h !== String(over) + mode){ warn.dataset.h = String(over) + mode; warn.innerHTML = h; enter(warn.firstChild); }
    else if (!over) $('.slx-left', warn).textContent = '$' + (cap - FC);
  }
  const at = e => { glide++; const b = bar.getBoundingClientRect(); cap = Math.round((MIN + (MAX - MIN) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width))) / 10) * 10; upd(); };
  bar.onpointerdown = e => { bar.setPointerCapture(e.pointerId); k.classList.add('drag'); at(e); bar.onpointermove = at; };
  bar.onpointerup = bar.onpointercancel = () => { k.classList.remove('drag'); bar.onpointermove = null; };
  k.onkeydown = e => { if (e.key === 'ArrowRight' || e.key === 'ArrowUp'){ cap = Math.min(MAX, cap + 10); upd(); e.preventDefault(); } if (e.key === 'ArrowLeft' || e.key === 'ArrowDown'){ cap = Math.max(MIN, cap - 10); upd(); e.preventDefault(); } };
  seg($('.slx-sg', r), m => { mode = m; upd(); });
  // typing a budget: the cap glides to it while it's in range; Enter or leaving the field keeps it (held to the range), Escape goes back
  let glide = 0, before = cap;
  const goTo = n => { const id = ++glide, from = cap; tween(from, n, 450, x => { if (id === glide){ cap = Math.round(x); upd(); } }); };
  const commit = () => { const n = vin.value === '' ? before : Math.max(MIN, Math.min(MAX, parseInt(vin.value, 10))); vin.value = n; fit(); if (n !== cap) goTo(n); };
  // a click selects the whole figure at once, so typing replaces it
  v.addEventListener('pointerdown', e => { if (document.activeElement !== vin){ e.preventDefault(); vin.focus({ preventScroll:true }); } });
  vin.onfocus = () => { before = cap; vin.select(); };
  vin.oninput = () => { vin.value = vin.value.replace(/\D/g, '').slice(0, 4); fit(); const n = +vin.value; if (vin.value && n >= MIN && n <= MAX) goTo(n); };
  vin.onkeydown = e => {
    if (e.key === 'Enter'){ e.preventDefault(); vin.blur(); }
    else if (e.key === 'Escape'){ vin.value = before; goTo(before); vin.blur(); }
    else if (e.key === 'ArrowUp' || e.key === 'ArrowDown'){ e.preventDefault(); const n = Math.max(MIN, Math.min(MAX, (parseInt(vin.value, 10) || cap) + (e.key === 'ArrowUp' ? 10 : -10))); vin.value = n; fit(); goTo(n); }
  };
  vin.onblur = commit;
  used.style.width = 0; fc.style.width = 0; k.style.left = pct(cap) + '%'; fit();
  // the line under the bar is one line on track and a notice when the forecast passes the cap: the panel grows and shrinks
  // with it, staying centred in its stage (owner, 17 Nov)
  const root = $('.slx', r); c.offs.push(grow(root));
  c.later(200, () => upd());
  // the preview lowers the cap once on its own, unless you take over first
  c.auto(1500, () => tween(200, 170, 900, x => { if (!c.mine){ cap = Math.round(x / 10) * 10; upd(); } }));
});
